import{_ as t,c as o,o as d,ae as a}from"./chunks/framework.CFeneB-q.js";const h=JSON.parse('{"title":"PC · Commit Convention","description":"","frontmatter":{},"headers":[],"relativePath":"en/pc/standards/commit-specification.md","filePath":"en/pc/standards/commit-specification.md","lastUpdated":1789438865000}'),r={name:"en/pc/standards/commit-specification.md"};function c(n,e,i,s,m,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="pc-·-commit-convention" tabindex="-1">PC · Commit Convention <a class="header-anchor" href="#pc-·-commit-convention" aria-label="Permalink to &quot;PC · Commit Convention&quot;">​</a></h1><blockquote><p>Aligned with the commitizen + commitlint setup of <code>keystone-deliver-ui</code> (verified 2026-09-16).</p></blockquote><h2 id="commit-message-format" tabindex="-1">Commit message format <a class="header-anchor" href="#commit-message-format" aria-label="Permalink to &quot;Commit message format&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope&gt;): &lt;subject&gt;</span></span></code></pre></div><p><strong>type</strong> enum (from <code>.cz-config.js</code>):</p><table tabindex="0"><thead><tr><th>type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>feature</code></td><td>New feature</td></tr><tr><td><code>bug</code></td><td>Bug listed in the QA feedback list</td></tr><tr><td><code>fix</code></td><td>Defect fix</td></tr><tr><td><code>ui</code></td><td>UI / style adjustment</td></tr><tr><td><code>docs</code></td><td>Documentation</td></tr><tr><td><code>style</code></td><td>Formatting only, no logic change</td></tr><tr><td><code>perf</code></td><td>Performance optimization</td></tr><tr><td><code>refactor</code></td><td>Refactoring (neither feature nor fix)</td></tr><tr><td><code>release</code></td><td>Release</td></tr><tr><td><code>deploy</code></td><td>Deployment related</td></tr><tr><td><code>test</code></td><td>Test related</td></tr><tr><td><code>chore</code></td><td>Build process or tooling changes</td></tr><tr><td><code>revert</code></td><td>Revert</td></tr><tr><td><code>build</code></td><td>Packaging</td></tr><tr><td><code>merge</code></td><td>Branch merge (allowed by commitlint only, not in the cz menu)</td></tr></tbody></table><ul><li><strong>scope is required</strong> (commitlint <code>scope-empty: never</code>) — use the module / business domain, e.g. <code>qual_mgmt</code>, <code>cfg_center</code>, <code>http</code>;</li><li><strong>subject</strong>: ≤ 72 characters, concise, no trailing period;</li><li><strong>body / footer</strong>: skipped by the cz prompts; generally not used.</li></ul><p>Examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feature(qual_mgmt): 新增回弹仪试验页面</span></span>\n<span class="line"><span>bug(personnel_mgmt): 修复考勤记录分页重复</span></span>\n<span class="line"><span>chore(env): 切换 pzgc 生产 API 地址</span></span></code></pre></div><h2 id="interactive-commits-pnpm-commit" tabindex="-1">Interactive commits: <code>pnpm commit</code> <a class="header-anchor" href="#interactive-commits-pnpm-commit" aria-label="Permalink to &quot;Interactive commits: `pnpm commit`&quot;">​</a></h2><p>The project uses commitizen (cz-customizable). <strong>Always prefer <code>pnpm commit</code> over <code>git commit</code></strong> — the prompts produce messages in the format above.</p><div class="warning custom-block"><p class="custom-block-title">Enforcement status (as-is)</p><p>husky currently only installs <strong>pre-commit (lint-staged); there is no commit-msg hook</strong> — commitlint rules are not auto-enforced. Compliance relies on the <code>pnpm commit</code> flow plus MR review.</p></div><h2 id="branch-naming" tabindex="-1">Branch naming <a class="header-anchor" href="#branch-naming" aria-label="Permalink to &quot;Branch naming&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Branch</th><th>Description</th></tr></thead><tbody><tr><td><code>master</code></td><td>Production branch; locked</td></tr><tr><td><code>stable</code></td><td>Pre-release branch (dev/test environments); locked</td></tr><tr><td><code>dev/feature-name</code></td><td>Regular development branch</td></tr><tr><td><code>hotfix/bug-name</code></td><td>Urgent fix; merge to <code>master</code> immediately for verification</td></tr><tr><td><code>fix/bug-name</code></td><td>General fix, e.g. <code>fix/#709-712</code></td></tr><tr><td><code>feat/feature-name</code></td><td>New feature development</td></tr><tr><td><code>refactor/feature-name</code></td><td>Refactoring</td></tr><tr><td><code>perf/optimization-content</code></td><td>Performance optimization</td></tr></tbody></table><h2 id="mr-review-release-flow" tabindex="-1">MR review &amp; release flow <a class="header-anchor" href="#mr-review-release-flow" aria-label="Permalink to &quot;MR review &amp; release flow&quot;">​</a></h2><ol><li><code>dev/* / feat/* / fix/*</code> → MR → review → merge to <code>stable</code> → released to dev/test for verification;</li><li>After verification, <code>stable</code> merges to <code>master</code> for production release;</li><li><code>hotfix/*</code> branches from <code>master</code>, merges back, then syncs to <code>stable</code>;</li><li>Keep branches clean and single-purpose; pull remote updates every morning before developing.</li></ol><hr><p><strong>Owner</strong>: E9 Frontend Team ｜ <strong>Last verified</strong>: 2026-09-16 ｜ <strong>Blueprint</strong>: <code>keystone-deliver-ui</code></p>',18)])])}const g=t(r,[["render",c]]);export{h as __pageData,g as default};
